import networkx as nx
import random

def has_girth_at_least_6(G):
    try:
        return nx.girth(G) >= 6
    except:
        # if not connected or something
        for cycle in nx.cycle_basis(G):
            if len(cycle) < 6:
                return False
        # better to use simple_cycles but slow
        return True

def find_graph():
    random.seed(42)  # for reproducibility
    for trial in range(5000):
        deg_seq = [random.randint(3,6) for _ in range(15)]
        if sum(deg_seq) % 2 != 0:
            deg_seq[0] += 1 if deg_seq[0] < 6 else -1
        try:
            G = nx.configuration_model(deg_seq, create_using=nx.Graph)
            G.remove_edges_from(nx.selfloop_edges(G))
            if len(G) < 15 or not nx.is_connected(G):
                continue
            degrees = [d for n,d in G.degree()]
            if min(degrees) < 3 or max(degrees) > 6:
                continue
            if has_girth_at_least_6(G):
                return sorted([tuple(sorted(e)) for e in G.edges()])
        except:
            continue
    return "UNSATISFIABLE"

result = find_graph()
print(result)
print(len(result) if isinstance(result, list) else result)
